const OH = 'http://openhab-production.openhab:8080/rest/persistence/items';
const ITEMS = [
  'SigenStor_Battery_SOC',
  'SigenStor_Battery_Power',
  'SigenStor_Grid_Power',
  'SigenStor_PV_Power',
  'SigenStor_Load_Power',
  'SigenStor_EVAC_Power',
  'SigenStor_Batt_Charged_Today',
  'SigenStor_Batt_Discharged_Today',
  'SigenStor_Battery_SOH',
];
const CAP = 18.0; // nominell batterikapacitet, kWh
const CHARGE_EFFICIENCY = 0.95; // endast för värdering av SOC-förändring
const STEP_MS = 60 * 1000;
const STALE_MS = 150 * 1000;
const pad = n => String(n).padStart(2, '0');
const dstr = d => `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())}`;
const TZ = 'Europe/Stockholm';
// Code-noden körs i UTC oavsett n8n:s tidszon. Dygnsgränser räknas därför
// uttryckligen i svensk tid. Ett dygn bärs som ett Date vars UTC-fält är det
// svenska kalenderdatumet (kl 12 UTC).
const tzParts = new Intl.DateTimeFormat('en-US', {
  timeZone: TZ, hourCycle: 'h23', year: 'numeric', month: 'numeric', day: 'numeric',
  hour: 'numeric', minute: 'numeric', second: 'numeric',
});
function wallClock(t) {
  const p = {};
  for (const part of tzParts.formatToParts(new Date(t))) {
    if (part.type !== 'literal') p[part.type] = Number(part.value);
  }
  return p;
}
function tzOffsetMs(t) {
  const p = wallClock(t);
  return Date.UTC(p.year, p.month - 1, p.day, p.hour, p.minute, p.second) - Math.floor(t / 1000) * 1000;
}
// Epoch-ms för svensk midnatt vid början av dygnet (plus addDays dygn).
function localMidnight(day, addDays = 0) {
  const wall = Date.UTC(day.getUTCFullYear(), day.getUTCMonth(), day.getUTCDate() + addDays);
  const guess = wall - tzOffsetMs(wall);
  return wall - tzOffsetMs(guess);
}
function yesterdayLocal() {
  const p = wallClock(Date.now());
  return new Date(Date.UTC(p.year, p.month - 1, p.day - 1, 12));
}
const sum = (a, key) => a.reduce((s, x) => s + (x[key] || 0), 0);

async function fetchDay(helpers, day) {
  const st = new Date(localMidnight(day)).toISOString();
  const et = new Date(localMidnight(day, 1)).toISOString();
  const res = {};
  for (const item of ITEMS) {
    try {
      const reply = await helpers.httpRequest({
        method: 'GET',
        url: `${OH}/${item}?starttime=${st}&endtime=${et}`,
        json: true,
      });
      res[item] = reply.data || [];
    } catch (error) {
      res[item] = [];
    }
  }
  let spot = [];
  try {
    spot = await helpers.httpRequest({
      method: 'GET',
      url: `https://www.elprisetjustnu.se/api/v1/prices/${day.getUTCFullYear()}/${pad(day.getUTCMonth() + 1)}-${pad(day.getUTCDate())}_SE3.json`,
      json: true,
      headers: { 'User-Agent': 'openhab-sigenstor-report/2.0' },
    });
  } catch (error) {
    spot = [];
  }
  return { res, spot };
}

function numericState(point) {
  const value = parseFloat(String(point.state).split(' ')[0]);
  return Number.isFinite(value) ? value : null;
}

function pointsFor(rows) {
  return (rows || [])
    .map(point => ({ t: Number(point.time), v: numericState(point) }))
    .filter(point => Number.isFinite(point.t) && point.v !== null)
    .sort((a, b) => a.t - b.t);
}

function sampler(rows) {
  const points = pointsFor(rows);
  const gaps = [];
  for (let i = 1; i < points.length; i += 1) {
    const gap = points[i].t - points[i - 1].t;
    if (gap > 0 && gap <= 60 * STEP_MS) gaps.push(gap);
  }
  gaps.sort((a, b) => a - b);
  const cadenceMs = gaps.length ? gaps[Math.floor(gaps.length / 2)] : STEP_MS;
  // Äldre rrd4j-historik är nedproverad. Ett regelbundet 15-minutersprov
  // representerar sitt intervall och ska inte misstolkas som 80 % databortfall.
  const maxAgeMs = Math.max(STALE_MS, Math.min(30 * STEP_MS, cadenceMs * 1.5));
  let index = 0;
  let last = null;
  return {
    points,
    cadenceMinutes: cadenceMs / STEP_MS,
    at(t) {
      while (index < points.length && points[index].t <= t) {
        last = points[index];
        index += 1;
      }
      return last && t - last.t <= maxAgeMs ? last.v : null;
    },
  };
}

function priceBands(spot) {
  return (spot || [])
    .map(point => ({
      start: Date.parse(point.time_start),
      end: Date.parse(point.time_end),
      spotKr: Number(point.SEK_per_kWh),
    }))
    .filter(point => Number.isFinite(point.start) && Number.isFinite(point.end) && Number.isFinite(point.spotKr))
    .sort((a, b) => a.start - b.start);
}

function buildPriceSampler(spot) {
  const bands = priceBands(spot);
  let index = 0;
  return {
    bands,
    at(t) {
      while (index < bands.length && t >= bands[index].end) index += 1;
      const band = bands[index];
      return band && t >= band.start && t < band.end ? band : null;
    },
  };
}

function localTime(t) {
  return new Date(t).toLocaleTimeString('sv-SE', {
    hour: '2-digit',
    minute: '2-digit',
    hourCycle: 'h23',
    timeZone: 'Europe/Stockholm',
  });
}

function mergeFlowBlocks(quarters, type, energyKey, valueKey, threshold) {
  const blocks = [];
  for (const quarter of quarters) {
    const energy = quarter[energyKey] || 0;
    if (energy < threshold) continue;
    const previous = blocks[blocks.length - 1];
    if (previous && previous.end === quarter.start) {
      previous.end = quarter.end;
      previous.energy += energy;
      previous.value += quarter[valueKey] || 0;
      previous.spotWeighted += (quarter.spotWeighted || 0);
      previous.spotHours += (quarter.spotHours || 0);
    } else {
      blocks.push({
        type,
        start: quarter.start,
        end: quarter.end,
        energy,
        value: quarter[valueKey] || 0,
        spotWeighted: quarter.spotWeighted || 0,
        spotHours: quarter.spotHours || 0,
      });
    }
  }
  return blocks;
}

function buildEvents(quarterMap) {
  const quarters = [...quarterMap.values()].sort((a, b) => a.start - b.start);
  const blocks = [
    ...mergeFlowBlocks(quarters, 'gridCharge', 'gridChargeKwh', 'gridChargeCost', 0.05),
    ...mergeFlowBlocks(quarters, 'batteryToLoad', 'batteryToLoadKwh', 'avoidedImportValue', 0.10),
    ...mergeFlowBlocks(quarters, 'export', 'exportKwh', 'exportRevenue', 0.05),
    ...mergeFlowBlocks(quarters, 'solarCharge', 'solarChargeKwh', 'solarOpportunityCost', 0.05),
    ...mergeFlowBlocks(quarters, 'ev', 'evKwh', 'zero', 0.10),
  ].sort((a, b) => a.start - b.start || a.type.localeCompare(b.type));

  return blocks.map(block => {
    const range = `${localTime(block.start)}–${localTime(block.end)}`;
    const energy = block.energy.toFixed(2);
    if (block.type === 'gridCharge') {
      const unit = block.energy ? block.value / block.energy * 100 : 0;
      return `${range} NÄTLADDNING ${energy} kWh @ snittköp ${unit.toFixed(0)} öre/kWh`;
    }
    if (block.type === 'batteryToLoad') {
      const unit = block.energy ? block.value / block.energy * 100 : 0;
      return `${range} BATTERI→LAST ${energy} kWh @ undviket nätköp ${unit.toFixed(0)} öre/kWh`;
    }
    if (block.type === 'export') {
      const unit = block.energy ? block.value / block.energy * 100 : 0;
      return `${range} EXPORT ${energy} kWh @ snittsälj ${unit.toFixed(0)} öre/kWh`;
    }
    if (block.type === 'solarCharge') {
      return `${range} SOLLADDNING ${energy} kWh (alternativ exportintäkt ${block.value.toFixed(2)} kr)`;
    }
    const avgSpot = block.spotHours ? block.spotWeighted / block.spotHours * 100 : null;
    return `${range} BILLADDNING ${energy} kWh${avgSpot === null ? '' : ` @ snittspot ${avgSpot.toFixed(0)} öre/kWh`}`;
  });
}

function analyseDay(day, res, spot) {
  const start = localMidnight(day);
  const end = localMidnight(day, 1);
  const totalMinutes = Math.round((end - start) / STEP_MS);

  const bat = sampler(res.SigenStor_Battery_Power);
  const grid = sampler(res.SigenStor_Grid_Power);
  const pv = sampler(res.SigenStor_PV_Power);
  const load = sampler(res.SigenStor_Load_Power);
  const ev = sampler(res.SigenStor_EVAC_Power);
  const soc = sampler(res.SigenStor_Battery_SOC);
  const prices = buildPriceSampler(spot);
  const resolutionMinutes = Math.max(
    bat.cadenceMinutes,
    grid.cadenceMinutes,
    pv.cadenceMinutes,
    load.cadenceMinutes,
  );
  const quarterMap = new Map();

  const totals = {
    pvKwh: 0,
    loadKwh: 0,
    evKwh: 0,
    impKwh: 0,
    impC: 0,
    expKwh: 0,
    expR: 0,
    batChg: 0,
    batDis: 0,
    gridChargeKwh: 0,
    gridChargeCost: 0,
    solarChargeKwh: 0,
    solarOpportunityCost: 0,
    batteryToLoadKwh: 0,
    avoidedImportValue: 0,
    batteryToExportKwh: 0,
    batteryExportRevenue: 0,
  };
  let coveredMinutes = 0;
  let pricedMinutes = 0;

  for (let t = start; t < end; t += STEP_MS) {
    const batPower = bat.at(t);
    const gridPower = grid.at(t);
    const pvPower = pv.at(t);
    const loadPower = load.at(t);
    const evPower = ev.at(t) || 0;
    if ([batPower, gridPower, pvPower, loadPower].some(value => value === null)) continue;
    coveredMinutes += 1;

    const band = prices.at(t);
    const spotKr = band ? band.spotKr : null;
    const buy = spotKr === null ? null : (spotKr + 0.667) * 1.25;
    const sell = spotKr === null ? null : spotKr + 0.06;
    if (band) pricedMinutes += 1;

    const dt = 1 / 60;
    const charge = Math.max(batPower, 0);
    const discharge = Math.max(-batPower, 0);
    const imported = Math.max(gridPower, 0);
    const exported = Math.max(-gridPower, 0);
    const gridCharge = Math.min(charge, imported);
    const solarCharge = Math.max(charge - gridCharge, 0);
    // Konservativ marginalallokering: samtidig export tillskrivs batteriet först.
    const batteryToExport = Math.min(discharge, exported);
    const batteryToLoad = Math.min(Math.max(discharge - batteryToExport, 0), Math.max(loadPower, 0));

    totals.pvKwh += Math.max(pvPower, 0) * dt;
    totals.loadKwh += Math.max(loadPower, 0) * dt;
    totals.evKwh += Math.max(evPower, 0) * dt;
    totals.impKwh += imported * dt;
    totals.expKwh += exported * dt;
    totals.batChg += charge * dt;
    totals.batDis += discharge * dt;
    totals.gridChargeKwh += gridCharge * dt;
    totals.solarChargeKwh += solarCharge * dt;
    totals.batteryToLoadKwh += batteryToLoad * dt;
    totals.batteryToExportKwh += batteryToExport * dt;

    const quarterStart = Math.floor(t / (15 * STEP_MS)) * 15 * STEP_MS;
    const quarter = quarterMap.get(quarterStart) || {
      start: quarterStart,
      end: quarterStart + 15 * STEP_MS,
      gridChargeKwh: 0,
      gridChargeCost: 0,
      batteryToLoadKwh: 0,
      avoidedImportValue: 0,
      exportKwh: 0,
      exportRevenue: 0,
      solarChargeKwh: 0,
      solarOpportunityCost: 0,
      evKwh: 0,
      spotWeighted: 0,
      spotHours: 0,
      zero: 0,
    };
    quarter.gridChargeKwh += gridCharge * dt;
    quarter.batteryToLoadKwh += batteryToLoad * dt;
    quarter.exportKwh += exported * dt;
    quarter.solarChargeKwh += solarCharge * dt;
    quarter.evKwh += Math.max(evPower, 0) * dt;

    if (band) {
      totals.impC += imported * buy * dt;
      totals.expR += exported * sell * dt;
      totals.gridChargeCost += gridCharge * buy * dt;
      totals.solarOpportunityCost += solarCharge * sell * dt;
      totals.avoidedImportValue += batteryToLoad * buy * dt;
      totals.batteryExportRevenue += batteryToExport * sell * dt;
      quarter.gridChargeCost += gridCharge * buy * dt;
      quarter.avoidedImportValue += batteryToLoad * buy * dt;
      quarter.exportRevenue += exported * sell * dt;
      quarter.solarOpportunityCost += solarCharge * sell * dt;
      quarter.spotWeighted += spotKr * dt;
      quarter.spotHours += dt;
    }
    quarterMap.set(quarterStart, quarter);
  }

  const socPoints = soc.points.filter(point => point.t >= start && point.t <= end);
  const socStart = socPoints.length ? socPoints[0].v : null;
  const socEnd = socPoints.length ? socPoints[socPoints.length - 1].v : null;
  const socMin = socPoints.length ? Math.min(...socPoints.map(point => point.v)) : null;
  const socMax = socPoints.length ? Math.max(...socPoints.map(point => point.v)) : null;
  const socDeltaKwh = socStart === null || socEnd === null ? null : (socEnd - socStart) * CAP / 100;

  const acquisitionCost = totals.gridChargeCost + totals.solarOpportunityCost;
  const chargeInput = totals.gridChargeKwh + totals.solarChargeKwh;
  const minimumBuy = prices.bands.length
    ? Math.min(...prices.bands.map(point => (point.spotKr + 0.667) * 1.25))
    : 0;
  const inventoryRate = chargeInput > 0.05
    ? acquisitionCost / chargeInput / CHARGE_EFFICIENCY
    : minimumBuy / CHARGE_EFFICIENCY;
  const inventoryAdjustment = socDeltaKwh === null ? 0 : socDeltaKwh * inventoryRate;
  const batteryValueBeforeCarry = totals.avoidedImportValue + totals.batteryExportRevenue
    - totals.gridChargeCost - totals.solarOpportunityCost;
  const batteryValue = batteryValueBeforeCarry + inventoryAdjustment;
  const legacyNet = totals.expR - totals.gridChargeCost;
  const coverage = totalMinutes ? coveredMinutes / totalMinutes : 0;
  const priceCoverage = coveredMinutes ? pricedMinutes / coveredMinutes : 0;
  const largeCarry = socDeltaKwh !== null && Math.abs(socDeltaKwh) > CAP * 0.10;
  const coarseHistory = resolutionMinutes > 5;
  const confidence = coverage < 0.95 || priceCoverage < 0.95 || socDeltaKwh === null
    ? 'låg'
    : largeCarry || coarseHistory ? 'medel' : 'hög';

  const last = item => {
    const values = pointsFor(res[item]);
    return values.length ? values[values.length - 1].v : null;
  };
  const spotsOre = prices.bands.map(point => point.spotKr * 100);
  return {
    datum: dstr(day),
    ...totals,
    legacyNet,
    batteryValueBeforeCarry,
    batteryValue,
    inventoryAdjustment,
    inventoryRate,
    socStart,
    socEnd,
    socMin,
    socMax,
    socDeltaKwh,
    cycles: (totals.batChg + totals.batDis) / (2 * CAP),
    soh: last('SigenStor_Battery_SOH'),
    counterCharged: last('SigenStor_Batt_Charged_Today'),
    counterDischarged: last('SigenStor_Batt_Discharged_Today'),
    spread: spotsOre.length ? Math.max(...spotsOre) - Math.min(...spotsOre) : 0,
    events: buildEvents(quarterMap),
    coverage,
    priceCoverage,
    coveredMinutes,
    totalMinutes,
    confidence,
    resolutionMinutes,
  };
}

function dayTable(a) {
  const soc = a.socStart === null || a.socEnd === null
    ? '?'
    : `${a.socStart.toFixed(0)} → ${a.socEnd.toFixed(0)} % (${a.socDeltaKwh >= 0 ? '+' : ''}${a.socDeltaKwh.toFixed(1)} kWh)`;
  return [
    `| Nyckeltal | Värde |`,
    `|---|---|`,
    `| Solproduktion | ${a.pvKwh.toFixed(1)} kWh |`,
    `| Husets förbrukning (exkl. bil) | ${Math.max(a.loadKwh - a.evKwh, 0).toFixed(1)} kWh |`,
    `| Elbilsladdning (EVAC) | ${a.evKwh.toFixed(1)} kWh |`,
    `| Import totalt | ${a.impKwh.toFixed(1)} kWh (${a.impC.toFixed(2)} kr) |`,
    `| Export totalt | ${a.expKwh.toFixed(1)} kWh (${a.expR.toFixed(2)} kr) |`,
    `| Nätladdning av batteri | ${a.gridChargeKwh.toFixed(1)} kWh (${a.gridChargeCost.toFixed(2)} kr) |`,
    `| Batteri till huslast | ${a.batteryToLoadKwh.toFixed(1)} kWh (undviket köp ${a.avoidedImportValue.toFixed(2)} kr) |`,
    `| Batteri till export | ${a.batteryToExportKwh.toFixed(1)} kWh (${a.batteryExportRevenue.toFixed(2)} kr) |`,
    `| Solladdningens alternativkostnad | ${a.solarOpportunityCost.toFixed(2)} kr |`,
    `| Batterivärde före SOC-periodisering | ${a.batteryValueBeforeCarry.toFixed(2)} kr |`,
    `| SOC start→slut | ${soc} |`,
    `| SOC-periodisering (est.) | ${a.inventoryAdjustment >= 0 ? '+' : ''}${a.inventoryAdjustment.toFixed(2)} kr |`,
    `| **Batteriets ekonomiska bidrag (est.)** | **${a.batteryValue.toFixed(2)} kr** |`,
    `| Datakvalitet | ${a.confidence} (${(a.coverage * 100).toFixed(1)} % effekt, ${(a.priceCoverage * 100).toFixed(1)} % pris, ${a.resolutionMinutes.toFixed(0)} min upplösning) |`,
    `| Batteri laddat/urladdat | ${a.batChg.toFixed(1)} / ${a.batDis.toFixed(1)} kWh (${a.cycles.toFixed(2)} ekv. cykler) |`,
    `| Spot-spread | ${a.spread.toFixed(0)} öre/kWh |`,
    a.soh !== null ? `| Batteri SOH | ${a.soh.toFixed(1)} % |` : null,
  ].filter(Boolean).join('\n');
}

function periodSummary(per) {
  const first = per[0];
  const last = per[per.length - 1];
  const socStart = first ? first.socStart : null;
  const socEnd = last ? last.socEnd : null;
  const socDeltaKwh = socStart === null || socEnd === null ? null : (socEnd - socStart) * CAP / 100;
  const gridChargeCost = sum(per, 'gridChargeCost');
  const solarOpportunityCost = sum(per, 'solarOpportunityCost');
  const chargeInput = sum(per, 'gridChargeKwh') + sum(per, 'solarChargeKwh');
  const minimumRate = per.length ? Math.min(...per.map(day => day.inventoryRate || Infinity)) : 0;
  const inventoryRate = chargeInput > 0.05
    ? (gridChargeCost + solarOpportunityCost) / chargeInput / CHARGE_EFFICIENCY
    : Number.isFinite(minimumRate) ? minimumRate : 0;
  const inventoryAdjustment = socDeltaKwh === null ? 0 : socDeltaKwh * inventoryRate;
  const batteryValueBeforeCarry = sum(per, 'avoidedImportValue') + sum(per, 'batteryExportRevenue')
    - gridChargeCost - solarOpportunityCost;
  const coverage = per.length ? per.reduce((s, day) => s + day.coverage, 0) / per.length : 0;
  const priceCoverage = per.length ? per.reduce((s, day) => s + day.priceCoverage, 0) / per.length : 0;
  const largeCarry = socDeltaKwh !== null && Math.abs(socDeltaKwh) > CAP * 0.10;
  const resolutionMinutes = per.length ? Math.max(...per.map(day => day.resolutionMinutes || 0)) : 0;
  const confidence = coverage < 0.95 || priceCoverage < 0.95 || socDeltaKwh === null
    ? 'låg'
    : largeCarry || resolutionMinutes > 5 ? 'medel' : 'hög';
  return {
    socStart,
    socEnd,
    socDeltaKwh,
    inventoryAdjustment,
    batteryValueBeforeCarry,
    batteryValue: batteryValueBeforeCarry + inventoryAdjustment,
    coverage,
    priceCoverage,
    confidence,
    resolutionMinutes,
  };
}

const input = $input.first() ? $input.first().json : {};
const periodEnd = input.reportDate
  ? new Date(`${input.reportDate}T12:00:00Z`)
  : yesterdayLocal();
const days = [];
for (let offset = 6; offset >= 0; offset -= 1) {
  const day = new Date(periodEnd);
  day.setUTCDate(day.getUTCDate() - offset);
  days.push(day);
}
const per = [];
for (const day of days) {
  const { res, spot } = await fetchDay(this.helpers, day);
  per.push(analyseDay(day, res, spot));
}
const period = periodSummary(per);
const best = per.reduce((current, day) => day.batteryValue > current.batteryValue ? day : current, per[0]);
const weekTable = [
  `| Vecka | Värde |`,
  `|---|---|`,
  `| Solproduktion | ${sum(per, 'pvKwh').toFixed(1)} kWh |`,
  `| Elbilsladdning | ${sum(per, 'evKwh').toFixed(1)} kWh |`,
  `| Export totalt | ${sum(per, 'expKwh').toFixed(1)} kWh (${sum(per, 'expR').toFixed(2)} kr) |`,
  `| Nätladdning | ${sum(per, 'gridChargeKwh').toFixed(1)} kWh (${sum(per, 'gridChargeCost').toFixed(2)} kr) |`,
  `| Undviket nätköp via batteri | ${sum(per, 'batteryToLoadKwh').toFixed(1)} kWh (${sum(per, 'avoidedImportValue').toFixed(2)} kr) |`,
  `| Batteriexport | ${sum(per, 'batteryToExportKwh').toFixed(1)} kWh (${sum(per, 'batteryExportRevenue').toFixed(2)} kr) |`,
  `| Solladdningens alternativkostnad | ${sum(per, 'solarOpportunityCost').toFixed(2)} kr |`,
  `| Batterivärde före SOC-periodisering | ${period.batteryValueBeforeCarry.toFixed(2)} kr |`,
  `| SOC start→slut | ${period.socStart === null || period.socEnd === null ? '?' : `${period.socStart.toFixed(0)} → ${period.socEnd.toFixed(0)} % (${period.socDeltaKwh >= 0 ? '+' : ''}${period.socDeltaKwh.toFixed(1)} kWh)`} |`,
  `| SOC-periodisering (est.) | ${period.inventoryAdjustment >= 0 ? '+' : ''}${period.inventoryAdjustment.toFixed(2)} kr |`,
  `| **Batteriets ekonomiska bidrag (est.)** | **${period.batteryValue.toFixed(2)} kr** |`,
  `| Datakvalitet | ${period.confidence} (${(period.coverage * 100).toFixed(1)} % effekt, ${(period.priceCoverage * 100).toFixed(1)} % pris, ${period.resolutionMinutes.toFixed(0)} min upplösning) |`,
  `| Batteri-cykler | ${sum(per, 'cycles').toFixed(1)} |`,
  `| Bästa dag, daglig uppskattning | ${best.datum} (${best.batteryValue.toFixed(2)} kr) |`,
  per[per.length - 1].soh !== null ? `| Batteri SOH | ${per[per.length - 1].soh.toFixed(1)} % |` : null,
].filter(Boolean).join('\n');

const dayRows = per.map(day => [
  day.datum,
  day.pvKwh.toFixed(1),
  day.evKwh.toFixed(1),
  day.gridChargeKwh.toFixed(1),
  day.batteryToLoadKwh.toFixed(1),
  `${day.socDeltaKwh >= 0 ? '+' : ''}${day.socDeltaKwh.toFixed(1)}`,
  day.batteryValue.toFixed(2),
  day.confidence,
].join(' | ')).map(row => `| ${row} |`).join('\n');

const report = [
  `VECKA: ${per[0].datum} – ${per[per.length - 1].datum}`,
  `KALKYLMODELL: v2.0 — observerat batterivärde med undvikna nätköp, 15-minuterspris och SOC-periodisering`,
  `OBS: Beloppet är en spårbar uppskattning av batteriets bidrag, inte samma kontrafaktiska mått som MySigens intäktskalender.`,
  ``,
  `VECKOTABELL (återge EXAKT):`,
  weekTable,
  ``,
  `PER DAG (återge EXAKT):`,
